import torch


def _make_well_conditioned_matrix(m, n, dtype, device):
    g = torch.Generator(device="cpu")
    g.manual_seed(42)
    k = min(m, n)
    A = torch.randn(m, n, generator=g, dtype=torch.float64, device="cpu")
    U, _, Vh = torch.linalg.svd(A, full_matrices=False)
    S = torch.linspace(float(k), 1.0, k, dtype=torch.float64, device="cpu")
    result = (U * S) @ Vh
    return result.to(dtype=dtype).to(device)


def gen_inputs(ctx, device):
    shape = ctx["A__shape"]
    if len(shape) == 2:
        m, n = shape[0], shape[1]
        A = _make_well_conditioned_matrix(m, n, torch.float32, device)
    else:
        b, m, n = shape[0], shape[-2], shape[-1]
        A = torch.stack(
            [_make_well_conditioned_matrix(m, n, torch.float32, "cpu") for _ in range(b)]
        ).to(device)
    return {"A": A}


def run_correctness(A):
    return torch.linalg.svdvals(A.float()).to(A.dtype)


def run(A):
    return torch.linalg.svdvals(A)
